sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    let test = api.data.look_up_affiliation.results;
    let test0 = api.data.look_up_affiliation.results;
    let test1 = [];
    // console.warn("テストだよ"+test);
    console.warn(test0);
    let dept = '';
    for (let i = 0; i < test.length; i++) {
        test1 = test[i].affiliation_code._reference;
        console.warn(test1);

        if (test1.department_name_1.displayValue != '') {
            dept = dept + test1.department_name_1.displayValue + '　';
        }
        if (test1.department_name_2.displayValue != '') {
            dept = dept + test1.department_name_2.displayValue + '　';
        }
        if (test1.department_name_3.displayValue != '') {
            dept = dept + test1.department_name_3.displayValue + '　';
        }
        if (test1.department_name_4.displayValue != '') {
            dept = dept + test1.department_name_4.displayValue + '　';
        }
        if (test1.department_name_5.displayValue != '') {
            dept = dept + test1.department_name_5.displayValue + '　';
        }
        if (i != test.length-1) {
            dept += "兼" + "<br>";
        }
        console.warn(dept);
    }

    let test2 = [];
    let grade = '';
    for (let i = 0; i < test0.length; i++) {
        test2 = test0[i].position_name.displayValue;

        if (test2 != '') {
            grade = grade + test2;
        }

        if (i != test0.length - 1) {
            grade += "<br>";
        }
        console.warn(grade);
    }
    let num_var = api.state.num;
    let records_var = api.state.records;

    records_var[num_var].old_dept.displayValue = dept;
    records_var[num_var].old_title.displayValue = grade;

    // console.warn(test[i].affiliation_code._reference.department_name_4.displayValue);
}
